KG42.register("rules-c2b9618fef3ad514bd2e5c17",{"id":"22-decentralized_flexibility_markets::v141-c-R003","paper":"22-decentralized_flexibility_markets","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"The local contract-selection outputs identify an over-demanded trade for price-signal coordination, which increases that trade's seller price by Δp. Scope: Feedback from provisional local contract allocations during each iteration of distribution-network flexibility negotiation. Condition: The trade is selected by its buyer but not its seller, and its buyer price exceeds its seller price. The local contract-selection outputs identify an over-demanded trade for price-signal coordination, which increases that trade's buyer price by Δp. Scope: Feedback from provisional local contract allocations during each iteration of distribution-network flexibility negotiation. Condition: The trade is selected by its buyer but not its seller, and its buyer price does not exceed its seller price. Both buyer and seller prices for every trade are initialized to zero. Scope: Initialization of buyer and seller prices for all potential flexibility trades. Condition: Before iterative negotiation begins. Price negotiation is complete when an iteration produces no price changes. Scope: Termination of the iterative flexibility price-negotiation process. Condition: No price changes occur during an iteration. The DSO continues offering higher prices for unrealized contracts required to meet its demand constraints while those constraints remain unsatisfied. Scope: DSO buyer-side offers for unrealized flexibility contracts needed to meet distribution-network demand constraints. Condition: The DSO's demand constraints remain unsatisfied.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","coordination.price_signal"],"E":[{"edge_id":"v141-c-R003-E001","source":"clearing.local","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R003-C001","v141-c-R003-C002"],"evidence_ids":["v141-b-g01-E10","v141-b-g02-e23"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"DSO buyer-side offers for unrealized flexibility contracts needed to meet distribution-network demand constraints. | Feedback from provisional local contract allocations during each iteration of distribution-network flexibility negotiation. | Initialization of buyer and seller prices for all potential flexibility trades. | Termination of the iterative flexibility price-negotiation process.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E10","v141-b-g02-e21","v141-b-g02-e23","v141-b-g02-e24","v141-b-g02-e25"]},"x":[{"variable_id":"v141-c-R003-X001","symbol":"p^{b,(k)}_{ω}","meaning":"Buyer price assigned to trade ω in negotiation iteration k.","kind":"operational","domain":"Price values for trades ω ∈ Ω; source initializes to 0 and does not state explicit bounds.","unit":null,"indices":["ω ∈ Ω","iteration k"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e23"]},{"variable_id":"v141-c-R003-X002","symbol":"p^{s,(k)}_{ω}","meaning":"Seller price assigned to trade ω in negotiation iteration k.","kind":"operational","domain":"Price values for trades ω ∈ Ω; source initializes to 0 and does not state explicit bounds.","unit":null,"indices":["ω ∈ Ω","iteration k"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e23"]},{"variable_id":"v141-c-R003-X003","symbol":"p_{ω}","meaning":"Price specified by a contract for trade ω, used in the selected-contract tuple representation.","kind":"operational","domain":"Contract price value for trade ω ∈ Ω.","unit":null,"indices":["ω ∈ Ω"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e23"]},{"variable_id":"v141-c-R003-X004","symbol":"Φ^{(k)}","meaning":"Set of over-demanded trades in iteration k: trades selected by their buyer but not their seller.","kind":"operational","domain":"Subsets of Ω, i.e. 2^{Ω}.","unit":null,"indices":["iteration k"],"evidence_ids":["v141-b-g02-e23"]},{"variable_id":"v141-c-R003-X005","symbol":"Y^{*,k}_{i}","meaning":"Agent i's selected upstream contracts in iteration k.","kind":"operational","domain":"Subsets of agent i's available upstream contracts Y_i.","unit":null,"indices":["i ∈ A","iteration k"],"evidence_ids":["v141-b-g02-e22","v141-b-g02-e23"]},{"variable_id":"v141-c-R003-X006","symbol":"Z^{*,k}_{i}","meaning":"Agent i's selected downstream contracts in iteration k.","kind":"operational","domain":"Subsets of agent i's available downstream contracts Z_i.","unit":null,"indices":["i ∈ A","iteration k"],"evidence_ids":["v141-b-g02-e22","v141-b-g02-e23"]}],"theta":[{"parameter_id":"v141-c-R003-T001","symbol":"Ω","meaning":"Full set of flexibility trades in the market.","value":{"kind":"symbolic","number_value":null,"text_value":"Full set of trades in the market"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e23"]},{"parameter_id":"v141-c-R003-T002","symbol":"Δp","meaning":"Minimum price-increment added to a trade side's price for an over-demanded trade; the case study uses Δp = £0.005/kWh.","value":{"kind":"symbolic","number_value":null,"text_value":"Minimum price-increment Δp; case-study value £0.005/kWh"},"unit":"£/kWh (case study)","indices":[],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e23","v141-b-g02-e29"]},{"parameter_id":"v141-c-R003-T003","symbol":"A","meaning":"Set of agents in the trading network.","value":{"kind":"symbolic","number_value":null,"text_value":"Set of agents in the trading network"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E13","v141-b-g02-e21"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"The local contract-selection outputs identify an over-demanded trade for price-signal coordination, which increases that trade's seller price by Δp. Scope: Feedback from provisional local contract allocations during each iteration of distribution-network flexibility negotiation. Condition: The trade is selected by its buyer but not its seller, and its buyer price exceeds its seller price.","expression":"Φ^{(k)} = {ω ∈ Ω | (ω, t_ω, p_ω) ∈ Y^{*,k}_{b(ω)} and ω ∉ Z^{*,k}_{s(ω)}}; ∀ω ∈ Φ^{(k)}, if p^{b,(k)}_{ω} > p^{s,(k)}_{ω} then p^{s,(k+1)}_{ω} = p^{s,(k)}_{ω} + Δp","formalization_origin":"source","template_id":null,"members":["clearing.local","coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002","v141-c-R003-X003","v141-c-R003-X004","v141-c-R003-X005","v141-c-R003-X006"],"parameter_refs":["v141-c-R003-T001","v141-c-R003-T002"],"evidence_ids":["v141-b-g01-E10","v141-b-g02-e23"]},{"constraint_id":"v141-c-R003-C002","kind":"procedural","role":"core","statement":"The local contract-selection outputs identify an over-demanded trade for price-signal coordination, which increases that trade's buyer price by Δp. Scope: Feedback from provisional local contract allocations during each iteration of distribution-network flexibility negotiation. Condition: The trade is selected by its buyer but not its seller, and its buyer price does not exceed its seller price.","expression":"Φ^{(k)} = {ω ∈ Ω | (ω, t_ω, p_ω) ∈ Y^{*,k}_{b(ω)} and ω ∉ Z^{*,k}_{s(ω)}}; ∀ω ∈ Φ^{(k)}, if p^{b,(k)}_{ω} ≤ p^{s,(k)}_{ω} then p^{b,(k+1)}_{ω} = p^{b,(k)}_{ω} + Δp","formalization_origin":"source","template_id":null,"members":["clearing.local","coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002","v141-c-R003-X003","v141-c-R003-X004","v141-c-R003-X005","v141-c-R003-X006"],"parameter_refs":["v141-c-R003-T001","v141-c-R003-T002"],"evidence_ids":["v141-b-g01-E10","v141-b-g02-e23"]},{"constraint_id":"v141-c-R003-C003","kind":"procedural","role":"core","statement":"Both buyer and seller prices for every trade are initialized to zero. Scope: Initialization of buyer and seller prices for all potential flexibility trades. Condition: Before iterative negotiation begins.","expression":"∀ω ∈ Ω, p^{b,(0)}_{ω} = 0 and p^{s,(0)}_{ω} = 0","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002"],"parameter_refs":["v141-c-R003-T001"],"evidence_ids":["v141-b-g02-e21"]},{"constraint_id":"v141-c-R003-C004","kind":"procedural","role":"core","statement":"Price negotiation is complete when an iteration produces no price changes. Scope: Termination of the iterative flexibility price-negotiation process. Condition: No price changes occur during an iteration.","expression":"Complete(k) ⇔ ∀ω ∈ Ω, p^{b,(k+1)}_{ω} = p^{b,(k)}_{ω} and p^{s,(k+1)}_{ω} = p^{s,(k)}_{ω}","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002"],"parameter_refs":["v141-c-R003-T001"],"evidence_ids":["v141-b-g02-e24"]},{"constraint_id":"v141-c-R003-C005","kind":"procedural","role":"core","statement":"The DSO continues offering higher prices for unrealized contracts required to meet its demand constraints while those constraints remain unsatisfied. Scope: DSO buyer-side offers for unrealized flexibility contracts needed to meet distribution-network demand constraints. Condition: The DSO's demand constraints remain unsatisfied.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e25"]}],"pi":[{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-12c011a9b5-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II. Decentralized Flexibility Market Design","anchor_text":"eir their willingness to accept a contract specifying a price for a unit of of demand reduction duri","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"unknown"},"source_text":"The agents reach mutual agreement on a set of agreed contracts and contract prices through an iterative price-negotiation mechanism. At each step of the market, agents select their favorite bundle of available upstream and downstream contracts, and over-demanded contracts have their prices increased. The process continues until no price changes occur during an iteration."},{"evidence_id":"v141-b-g02-e21","location":{"location_id":"src-12c011a9b5-p06-c1r4__v141-a-M01-bidding","page":6,"printed_page":null,"section":"V.A Price-Negotiation Mechanism","anchor_text":"ω ∈Ω. The agents then engage in iterative negotiation with dow their neighbors. Each iteration: no r","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"A flow chart of the price-negotiation process is shown in Fig. 2. Each agent i \\in A starts by specifying the flexibility trades they may be willing to make. Let \\Omega be the full set of trades in the market. Each trade \\omega \\in \\Omega is assigned a buyer price p^{b}_{\\omega} and a seller price p^{s}_{\\omega}. Initially, p^{b}_{\\omega} = 0 and p^{s}_{\\omega} = 0 for all \\omega \\in \\Omega. The agents then engage in iterative negotiation with their neighbors. Each iteration: Each agent i \\in A constructs a set of upstream contracts to choose from, Y_i = \\{(\\omega, t_{\\omega}, p^{b}_{\\omega}) \\mid \\omega \\in \\Omega, b(\\omega) = i\\} and a set of downstream contracts to choose from, Z_i = \\{(\\omega, t_{\\omega}, p^{s}_{\\omega}) \\mid \\omega \\in \\Omega, s(\\omega) = i\\}."},{"evidence_id":"v141-b-g02-e23","location":{"location_id":"src-12c011a9b5-p06-c1r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"V.A Price-Negotiation Mechanism","anchor_text":"ω ∈Ω. The agents then engage in iterative negotiation with dow their neighbors. Each iteration: no r","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The prices of over-demanded trades are increased. The set of over-demanded trades is given by \\Phi = \\{\\omega \\in \\Omega \\mid (\\omega, t_{\\omega}, p_{\\omega}) \\in Y^{*}_{b(\\omega)}, \\omega \\notin Z^{*}_{s(\\omega)}\\}. For each \\omega \\in \\Phi, if p^{b}_{\\omega} > p^{s}_{\\omega}, then p^{s}_{\\omega} is increased by \\Delta p; otherwise, p^{b}_{\\omega} is increased by \\Delta p."},{"evidence_id":"v141-b-g02-e24","location":{"location_id":"src-12c011a9b5-p06-c2r1__v141-a-M01-coordination","page":6,"printed_page":null,"section":"V.A Price-Negotiation Mechanism","anchor_text":"ON SYSTEM FLEXIBILITY 2133 The negotiation is complete when no price changes occur during an iterati","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"The negotiation is complete when no price changes occur during an iteration. \\cup_{i\\in A} Y^{*}_i is a stable outcome for the trading network."},{"evidence_id":"v141-b-g02-e25","location":{"location_id":"src-12c011a9b5-p06-c2r1__v141-a-M01-coordination","page":6,"printed_page":null,"section":"V.A Price-Negotiation Mechanism","anchor_text":"ON SYSTEM FLEXIBILITY 2133 The negotiation is complete when no price changes occur during an iterati","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Note that if the prosumer resources have sufficient flexibility to satisfy the DSO's demand constraints, then the constraints will be satisfied at the end of the price-negotiation. The DSO will continue to offer higher prices for unrealized contracts required to meet its demand constraints, as long as the constraints are not satisfied. Eventually, these contracts will become sufficiently valuable, so that they are also selected by the associated prosumers and aggregators."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-12c011a9b5-p04-c1r1__v141-a-M01-participation","page":4,"printed_page":null,"section":"III. Agent Preferences","anchor_text":"MORSTYN et al.: DESIGNING DECENTRALIZED MARKETS FOR DISTRIBUTION SYSTE large number of consumers and","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"unknown"},"source_text":"Let A be the set of agents in the trading network. In the flexibility market, the agents trade flexibility contracts for a set of time intervals \\(\\mathcal{T} = \\{1, \\ldots, T\\}\\). Each flexibility contract specifies a price for a flexibility trade, specifying an agreed reduction in demand during a particular time interval. Note that all trades specify the same energy quantity of demand reduction. Let \\(X\\) be the set of contracts between the agents. A contract \\(x \\in X\\) can be described by a tuple \\((\\omega, t_\\omega, p_\\omega)\\), where \\(\\omega \\in \\Omega\\) is a unique trade ID, \\(t_\\omega\\) is the time interval of the underlying trade and \\(p_\\omega\\) is the price specified by the contract for the trade. The trades underlying a set of contracts \\(X\\) are given by \\(\\tau(X) = \\{\\omega \\in \\Omega | (\\omega, t_\\omega, p_\\omega) \\in X\\}\\)."},{"evidence_id":"v141-b-g02-e20","location":{"location_id":"src-12c011a9b5-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"V.A Price-Negotiation Mechanism","anchor_text":"Fig. 2. A ﬂowchart showing the agent-to-agent price-negotiation mechanism. fol A ﬂ is s the DSO, agg","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"unknown"},"source_text":"The proposed flexibility market design requires only individual decision making and agent-to-agent negotiation between the DSO, aggregators and prosumers. Agents wishing to obtain flexibility make progressively higher offers to potential sellers, and sellers choose to accept or reject these offers. Each iteration, the prices of over-demanded flexibility trades increase by a minimum price-increment \\Delta p, until each trade has been either selected by both its buyer and seller, or rejected by both its buyer and seller."},{"evidence_id":"v141-b-g02-e22","location":{"location_id":"src-12c011a9b5-p06-c1r4__v141-a-M01-bidding","page":6,"printed_page":null,"section":"V.A Price-Negotiation Mechanism","anchor_text":"ω ∈Ω. The agents then engage in iterative negotiation with dow their neighbors. Each iteration: no r","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Each agent i \\in A selects its favorite set of upstream contracts Y^{*}_i = C_i(Y_i \\cup Z_i) \\cap Y_i and downstream contracts Z^{*}_i = C_i(Y_i \\cup Z_i) \\cap Z_i."},{"evidence_id":"v141-b-g02-e29","location":{"location_id":"src-12c011a9b5-p07-c2r4__v141-a-M01-participation","page":7,"printed_page":null,"section":"VI. Results","anchor_text":"p p y, one hour standard deviations. ity The prosumers face time-of-use dependent retail energy her ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"unknown"},"source_text":"The flexibility market occurs over a 24 hour period (from 8 am to 8 am), with contracts specifying an agreed decrease in load by 1 kW during a particular 30 minute interval. A market price increment of \\Delta p = £0.005/kWh is used. For prosumers 1–30, the increased battery degradation that occurs at higher output powers is modeled with a quadratic cost coefficient c_{2i}. For Case Study A, c_{2i} = £0.01/(kWh)^2, whereas in Case Study B the rate of degradation is higher, c_{2i} = £0.06/(kWh)^2. It is assumed the batteries start at their minimum energy level at 8 am and must be returned to this energy level by 8 am the next day. For prosumers 31–45, it is assumed they need to fully re-charge their electric vehicles between their arrival and departure times, and also have a preference for early charging, with \\gamma_i = £0.01/kWh/h. The aggregators incur a transaction cost of c_{1i} = £0.01 for each accepted upstream contract."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E10","quote":"At each step of the market, agents select their favorite bundle of available upstream and downstream contracts, and over-demanded contracts have their prices increased."},{"evidence_id":"v141-b-g02-e23","quote":"The set of over-demanded trades is given by \\Phi = \\{\\omega \\in \\Omega \\mid (\\omega, t_{\\omega}, p_{\\omega}) \\in Y^{*}_{b(\\omega)}, \\omega \\notin Z^{*}_{s(\\omega)}\\}. For each \\omega \\in \\Phi, if p^{b}_{\\omega} > p^{s}_{\\omega}, then p^{s}_{\\omega} is increased by \\Delta p"}],[{"evidence_id":"v141-b-g01-E10","quote":"At each step of the market, agents select their favorite bundle of available upstream and downstream contracts, and over-demanded contracts have their prices increased."},{"evidence_id":"v141-b-g02-e23","quote":"The set of over-demanded trades is given by \\Phi = \\{\\omega \\in \\Omega \\mid (\\omega, t_{\\omega}, p_{\\omega}) \\in Y^{*}_{b(\\omega)}, \\omega \\notin Z^{*}_{s(\\omega)}\\}. For each \\omega \\in \\Phi, if p^{b}_{\\omega} > p^{s}_{\\omega}, then p^{s}_{\\omega} is increased by \\Delta p; otherwise, p^{b}_{\\omega} is increased by \\Delta p."}],[{"evidence_id":"v141-b-g02-e21","quote":"Initially, p^{b}_{\\omega} = 0 and p^{s}_{\\omega} = 0 for all \\omega \\in \\Omega."}],[{"evidence_id":"v141-b-g02-e24","quote":"The negotiation is complete when no price changes occur during an iteration."}],[{"evidence_id":"v141-b-g02-e25","quote":"The DSO will continue to offer higher prices for unrealized contracts required to meet its demand constraints, as long as the constraints are not satisfied."}]],"C2_formalization":{"graph_sha256":"abb50d94835fde5dd46910cb896cc6cf4667def81bbd18749fa555eabc74495b","applicability":"formalized","reason":"Source supplies explicit equations for over-demanded-trade price updates (C001-C002), zero price initialization (C003), and the no-price-change termination test (C004). These are formalized against coordination.price_signal with the clearing.local -> coordination.price_signal edge. C005 remains a narrative DSO continuation condition because the supplied quotations do not give a separate update equation. B evidence is unreviewed; this patch is provisional.","bindings":[{"object_id":"v141-c-R003-X001","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Buyer price is part of the coordination price-signal state; its update is triggered by local contract-selection outputs on the clearing.local -> coordination.price_signal edge."},{"object_id":"v141-c-R003-X002","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Seller price is part of the coordination price-signal state; its update is triggered by local contract-selection outputs on the clearing.local -> coordination.price_signal edge."},{"object_id":"v141-c-R003-X003","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Contract price element in the selected-contract tuple used to identify over-demanded trades, connecting clearing.local selection outputs to coordination.price_signal."},{"object_id":"v141-c-R003-X004","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"The over-demanded set is derived from clearing.local selections and consumed by coordination.price_signal on edge E001."},{"object_id":"v141-c-R003-X005","node_ids":["clearing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"Selected upstream contracts are clearing.local outputs that feed the price-signal coordination rule."},{"object_id":"v141-c-R003-X006","node_ids":["clearing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"Selected downstream contracts are clearing.local outputs that feed the price-signal coordination rule."},{"object_id":"v141-c-R003-T001","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"Ω defines the full trade set over which coordination.price_signal initializes and updates prices."},{"object_id":"v141-c-R003-T002","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Δp is the fixed price increment used when coordination.price_signal responds to clearing.local over-demand feedback."},{"object_id":"v141-c-R003-T003","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"The agent set A supplies the buyer/seller identities whose clearing.local selections are coordinated through coordination.price_signal."},{"object_id":"v141-c-R003-C001","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"C001 formalizes the seller-price branch of the over-demanded-trade update driven by clearing.local selection outputs on edge E001."},{"object_id":"v141-c-R003-C002","node_ids":["clearing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"C002 formalizes the buyer-price branch of the over-demanded-trade update driven by clearing.local selection outputs on edge E001."},{"object_id":"v141-c-R003-C003","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"C003 formalizes initialization of the coordination.price_signal price state before iterative negotiation."},{"object_id":"v141-c-R003-C004","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"C004 formalizes the termination test for no price changes in coordination.price_signal."}],"revision_requests":[]}},"quarantined_references":[]}});
